            url: 'https://example.test',
            title: 'Document bookmark',
            note: null,
            tags: ['one', 'two'],
          },
        ],
      },
    ],
  };
}

function validV1Document() {
  return {
    version: 1,
    preferences: { source: 'legacy' },
    links: [
      {
        key: 'legacy-id',
        href: 'https://legacy.example',
        caption: 'Legacy bookmark',
        memo: null,
        folder: 'legacy-folder',
        tags: ['legacy'],
      },
    ],
  };
}

