for (const [name, mutate] of invalidV2Cases) {
  test(`rejects invalid version 2 documents: ${name}`, () => {
    const library = seededLibrary();
    const document = validV2Document();

    mutate(document);
    assertRejectedAtomically(library, document, 'INVALID_DOCUMENT');
  });
}

